using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Pipes;
using System.Linq;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using AICad.Contracts;
using JsonUtil=AICad.Contracts.Json;
using Autodesk.AutoCAD.ApplicationServices;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Runtime;
using Newtonsoft.Json.Linq;
using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
[assembly:ExtensionApplication(typeof(AICad.Bridge.Plugin))]
[assembly:CommandClass(typeof(AICad.Bridge.Commands))]
namespace AICad.Bridge;
public sealed class Plugin:IExtensionApplication {
 internal static Plugin? Current;internal NativeContext Context=null!;internal InstallConfig Config=null!;internal NativeReview Review=null!;internal CadToolPalette? Tools;internal RainmakerRibbon? Ribbon;internal PlanFiles Plans=null!;internal string? NextPlan;internal JObject? NextSourceTask;internal readonly ConcurrentQueue<Action> Queue=new();readonly CancellationTokenSource stopping=new();SessionInfo registration=null!;string sessionFile="";NamedPipeServerStream? active;DateTime heartbeat;
 public void Initialize(){try{string install=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location)!,"..","install.json"));if(!Convert.ToString(AcApp.GetSystemVariable("ACADVER")).StartsWith("24.0",StringComparison.Ordinal))throw new CadException("UNSUPPORTED_CAD","This plugin targets AutoCAD 2021.");Config=JsonUtil.Read<InstallConfig>(File.ReadAllText(install));NativeLibraryAssets.ContentRoot=Config.ContentRoot;if(!File.Exists(Config.HostExecutable))throw new CadException("HOST_MISSING","Build the Host first.");PrepareRoot(Config.DataRoot);Directory.CreateDirectory(Path.Combine(Config.DataRoot,"sessions"));Context=new NativeContext();Plans=new PlanFiles(Config.DataRoot);using(var process=Process.GetCurrentProcess())registration=new SessionInfo{PluginVersion="0.7.12",SessionId=Context.SessionId,PipeName="aicad-"+Context.SessionId,Secret=Guid.NewGuid().ToString("N")+Guid.NewGuid().ToString("N"),ProcessId=process.Id,ProcessStartTicks=process.StartTime.ToUniversalTime().Ticks};sessionFile=Path.Combine(Config.DataRoot,"sessions",Context.SessionId+".json");if(Process.GetCurrentProcess().ProcessName.Equals("acad",StringComparison.OrdinalIgnoreCase)){Review=new NativeReview(this);Ribbon=new RainmakerRibbon(this);}Current=this;AcApp.Idle+=Idle;Publish();Task.Run(Listen);AcApp.DocumentManager.MdiActiveDocument?.Editor.WriteMessage("\nAI CAD MCP ready. AICAD opens the local review palette. AICADDEMO creates a new isolated demo DWG.");}catch(System.Exception e){AcApp.DocumentManager.MdiActiveDocument?.Editor.WriteMessage("\nAI CAD could not start: "+e.Message);}}
 internal static void PrepareRoot(string root){root=Path.GetFullPath(root);if(root.StartsWith("\\\\"))throw new CadException("UNSAFE_PATH","Local data directory required.");for(var p=new DirectoryInfo(root);p!=null;p=p.Parent)if(p.Exists&&(p.Attributes&FileAttributes.ReparsePoint)!=0)throw new CadException("UNSAFE_PATH","Linked directories are unsupported.");var dir=Directory.CreateDirectory(root);var security=new DirectorySecurity();security.SetAccessRuleProtection(true,false);using(var user=WindowsIdentity.GetCurrent())security.AddAccessRule(new FileSystemAccessRule(user.User,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));security.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(WellKnownSidType.LocalSystemSid,null),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));dir.SetAccessControl(security);}
 void Publish(){registration.HeartbeatUtc=DateTime.UtcNow;JsonUtil.Atomic(sessionFile,registration);heartbeat=DateTime.UtcNow;}
 void Idle(object sender,EventArgs e){if((DateTime.UtcNow-heartbeat).TotalSeconds>5)try{Publish();}catch(IOException){}Review?.ValidateLive();Ribbon?.Update();if(Convert.ToInt32(AcApp.GetSystemVariable("CMDACTIVE"))==0&&Queue.TryDequeue(out var work))work();}
 async Task Listen(){while(!stopping.IsCancellationRequested){try{var acl=new PipeSecurity();acl.SetAccessRuleProtection(true,false);using(var user=WindowsIdentity.GetCurrent())acl.AddAccessRule(new PipeAccessRule(user.User,PipeAccessRights.FullControl,AccessControlType.Allow));using(var pipe=new NamedPipeServerStream(registration.PipeName,PipeDirection.InOut,1,PipeTransmissionMode.Byte,PipeOptions.Asynchronous,4096,4096,acl)){active=pipe;await pipe.WaitForConnectionAsync(stopping.Token);using var timer=new Timer(_=>{try{pipe.Dispose();}catch{}},null,15000,Timeout.Infinite);if(!GetNamedPipeClientProcessId(pipe.SafePipeHandle,out var pid))continue;using(var client=Process.GetProcessById((int)pid))if(!string.Equals(Path.GetFullPath(client.MainModule.FileName),Path.GetFullPath(Config.HostExecutable),StringComparison.OrdinalIgnoreCase))continue;byte[] size=new byte[4];await Read(pipe,size);int length=BitConverter.ToInt32(size,0);if(length<1||length>1024*1024)continue;byte[] bytes=new byte[length];await Read(pipe,bytes);NativeResponse response;try{var request=JsonUtil.Read<NativeRequest>(Encoding.UTF8.GetString(bytes));if(!FixedEquals(request.Secret,registration.Secret))throw new CadException("UNAUTHENTICATED","Plugin secret differs.");var completion=new TaskCompletionSource<NativeResponse>(TaskCreationOptions.RunContinuationsAsynchronously);var deadline=DateTime.UtcNow.AddSeconds(10);if(Queue.Count>32)throw new CadException("BUSY","CAD request queue is full.");Queue.Enqueue(()=>{if(DateTime.UtcNow>deadline){completion.TrySetResult(new NativeResponse{Code="CAD_TIMEOUT",Message="Request expired before dispatch."});return;}try{completion.TrySetResult(new NativeResponse{Ok=true,Data=Dispatch(request)});}catch(CadException e){completion.TrySetResult(new NativeResponse{Code=e.Code,Message=e.Message});}catch(System.Exception e){completion.TrySetResult(new NativeResponse{Code="CAD_ERROR",Message=e.Message});}});response=await completion.Task;}catch(CadException e){response=new NativeResponse{Code=e.Code,Message=e.Message};}byte[] output=Encoding.UTF8.GetBytes(JsonUtil.Write(response));await pipe.WriteAsync(BitConverter.GetBytes(output.Length),0,4);await pipe.WriteAsync(output,0,output.Length);await pipe.FlushAsync();}}catch(System.Exception)when(!stopping.IsCancellationRequested){await Task.Delay(200);}catch(System.Exception){break;}}}
 static async Task Read(Stream pipe,byte[] data){int n=0;while(n<data.Length){int got=await pipe.ReadAsync(data,n,data.Length-n);if(got==0)throw new EndOfStreamException();n+=got;}}
 static bool FixedEquals(string a,string b){int diff=a.Length^b.Length;for(int i=0;i<Math.Min(a.Length,b.Length);i++)diff|=a[i]^b[i];return diff==0;}
 [DllImport("kernel32",SetLastError=true)]static extern bool GetNamedPipeClientProcessId(Microsoft.Win32.SafeHandles.SafePipeHandle pipe,out uint pid);
 JToken Dispatch(NativeRequest r){if(r.Method=="list_documents")return JArray.FromObject(Context.Open.Keys.Select(Context.Info));var d=Context.Resolve(r.DocumentId,r.Revision);if(r.Method=="get_document_info"){var info=JObject.FromObject(Context.Info(d));info["revisionCauses"]=new JArray(Context.RevisionCauses);return info;}if(r.Method=="scan_task_blocks")return JArray.FromObject(Reader.Scan(d));if(r.Method=="get_entities")return Reader.Read(d,r.Params);if(r.Method=="inspect_execution")return Reader.Inspect(d,Plans,r.Params.Value<string>("planId")??"");if(r.Method=="select_document"){AcApp.DocumentManager.MdiActiveDocument=d;return JObject.FromObject(Context.Info(d));}if(r.Method=="get_layers"){using var tx=d.Database.TransactionManager.StartOpenCloseTransaction();var table=(LayerTable)tx.GetObject(d.Database.LayerTableId,OpenMode.ForRead);return new JArray(table.Cast<ObjectId>().Take(1000).Select(id=>((LayerTableRecord)tx.GetObject(id,OpenMode.ForRead)).Name));}if(r.Method=="get_blocks"){using var tx=d.Database.TransactionManager.StartOpenCloseTransaction();var table=(BlockTable)tx.GetObject(d.Database.BlockTableId,OpenMode.ForRead);return new JArray(table.Cast<ObjectId>().Take(1000).Select(id=>((BlockTableRecord)tx.GetObject(id,OpenMode.ForRead)).Name));}if(r.Method=="prepare_source_task"){if(Review==null)throw new CadException("INTERACTIVE_REQUIRED","Can AutoCAD co giao dien.");if(d!=AcApp.DocumentManager.MdiActiveDocument)throw new CadException("ACTIVATE_DOCUMENT","Kich hoat DWG da chon.");if(NextSourceTask!=null)throw new CadException("BUSY","Dang chuan bi khung nguon.");NextSourceTask=(JObject)r.Params.DeepClone();NextSourceTask["documentId"]=r.DocumentId;NextSourceTask["revision"]=r.Revision;d.SendStringToExecute("AICADSOURCETASK\n",true,false,false);return new JObject{["status"]="QUEUED"};}if(r.Method=="create_preview"){if(Review==null)throw new CadException("INTERACTIVE_REQUIRED","Use graphical AutoCAD for preview and local approval.");if(d!=AcApp.DocumentManager.MdiActiveDocument)throw new CadException("ACTIVATE_DOCUMENT","Activate the selected DWG in AutoCAD, then retry preview.");if(NextPlan!=null)throw new CadException("BUSY","A review request is already queued.");NextPlan=JsonUtil.Id(r.Params.Value<string>("planId")??"");d.SendStringToExecute("AICADREVIEW\n",true,false,false);return new JObject{["status"]="QUEUED",["message"]="Open AutoCAD to view and approve the plan locally."};}throw new CadException("UNSUPPORTED_METHOD","Native endpoint does not expose arbitrary commands or approval.");}
 public void Terminate(){stopping.Cancel();active?.Dispose();AcApp.Idle-=Idle;Ribbon?.Remove();Review?.Dispose();Tools?.Dispose();Context?.Dispose();try{if(File.Exists(sessionFile))File.Delete(sessionFile);}catch(IOException){}Current=null;}
}
